    if options.Fflag {
      try fullname(pw);
      return
    }

    if options.gflag {
      let id = pw != nil ? pw!.groupId : (options.rflag ? groupId : effectiveGroupId)
      if options.nflag {
        let gr = getGroupEntry(of: id)
        if let gr {
          print(gr.name)
        } else {
          print(id)
        }
      }
      else {
        print(id)
      }
      return
    }
    
    if options.uflag {
      let id = pw != nil ? pw!.userId : options.rflag ? userId : effectiveUserId
      if options.nflag {
        if let pw = getPasswd(of: Int(id) ) {
          print(pw.name)
        } else {
          print(id)
        }
      }
      else {
        print(id)
      }
      return
    }
    
    if options.Gflag {
      group(pw, options.nflag )
      return
    }
    
    if options.Pflag {
      try pline(pw)
      return
    }
    
    if options.pflag {
      try pretty(pw);
      return
    }
    
    
    if options.flagCount == 0 {
      if let pw {
        id_print(pw, true, 0, 0);
      }
      else {
