  func pretty(_ pwx : Passwd?) throws(CmdErr) {
    var pw = pwx
    
    if let pw {
      print("uid\t\(pw.name)")
      print("groups\t", terminator: "")
      group(pw, true);
    } else {
      let login = userName
      let ridu = userId
      pw = getPasswd(of: ridu)
      if pw == nil || login != pw!.name {
        print("login\t\(login)");
      }
      if let pw {
        print("uid\t\(pw.name)");
      } else {
        print("uid\t\(ridu)");
      }
      
      let eidu = effectiveUserId
      if eidu != ridu {
